def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    if old_value == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "ones", "unit": "percent"}}}
    change_ratio = (new_value - old_value) / old_value
    percentage_change = change_ratio * 100
    return {
        "value": percentage_change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change_ratio": change_ratio,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percent"},
        },
    }
